    Bug 2063008 - Strip version suffix from Microsoft Graph service URLs. r=klamping

    Differential Revision: https://phabricator.services.mozilla.com/D318172

diff --git a/mail/components/accountcreation/content/widgets/email-exchange-settings.mjs b/mail/components/accountcreation/content/widgets/email-exchange-settings.mjs
index b607a522990..75446717cb0 100644
--- a/mail/components/accountcreation/content/widgets/email-exchange-settings.mjs
+++ b/mail/components/accountcreation/content/widgets/email-exchange-settings.mjs
@@ -122,6 +122,16 @@ class EmailExchangeSettings extends AccountHubStep {
     try {
       const inputValue = this.#serviceURL.value.trim();
       const url = InputSanitizer.url(inputValue);
+      const parsedURL = URL.parse(url);
+
+      if (
+        parsedURL.origin === "https://graph.microsoft.com" &&
+        ["/v1.0", "/v1.0/"].includes(parsedURL.pathname)
+      ) {
+        parsedURL.pathname = "/";
+        return parsedURL.href;
+      }
+
       return url;
     } catch {
       return "";
